import { describe, expect, it } from 'bun:test';
import { argon2 } from '../test-support/argon2';
import { Argon2Type, Argon2Version } from '../../lib/crypto/crypto-engine';
import vectors from './argon2-vectors.json';

// Golden outputs generated by the reference C implementation of Argon2.
// A changed value means existing databases would no longer decrypt.
const toBuffer = (hex: string): ArrayBuffer =>
    Uint8Array.from(Buffer.from(hex, 'hex')).buffer as ArrayBuffer;

describe('Argon2 golden vectors', () => {
    for (const v of vectors) {
        const name = `type=${v.type} v=0x${v.version.toString(16)} m=${v.memory} t=${v.iterations} p=${v.parallelism} len=${v.length} pw=${v.password.length / 2}`;
        it(name, async () => {
            const hash = await argon2(
                toBuffer(v.password),
                toBuffer(v.salt),
                v.memory,
                v.iterations,
                v.length,
                v.parallelism,
                v.type as Argon2Type,
                v.version as Argon2Version
            );
            expect(Buffer.from(hash).toString('hex')).toBe(v.hash);
        }, 120000);
    }
});
